#include "PresetManager.h"
#include "PluginProcessor.h"
#include "StorageManager.h"
#include <algorithm>

// Factory preset data - generated by CMake from presets/
// Uses separate namespace (FactoryPresetData) to avoid conflicts with icon BinaryData
#if HAS_FACTORY_PRESETS
    #include "FactoryPresetData.h"
#endif

PresetManager::PresetManager(juce::AudioProcessor& processor,
                             juce::AudioProcessorValueTreeState& apvts)
    : audioProcessor(processor)
    , parameters(apvts)
{
    // 1. Create directory structure
    initializePresetDirectories();

    // 2. Migrate existing presets from old location (data root → Presets/)
    migratePresetsIfNeeded();

    // 3. Install factory presets from BinaryData to disk (first launch or version update)
    installFactoryPresetsIfNeeded();

    // 4. Create in-memory factory preset (Init)
    loadFactoryPresets();

    // 5. Scan all presets from disk (includes installed factory presets)
    scanUserPresets();
}

void PresetManager::savePreset(const juce::String& presetName)
{
    auto presetDir = getUserPresetDirectory();

    // Ensure the directory exists
    if (!presetDir.exists())
        presetDir.createDirectory();

    juce::File presetFile = presetDir.getChildFile(presetName + ".xml");

    auto xml = createPresetXml(presetName);

    if (xml != nullptr)
    {
        bool success = xml->writeTo(presetFile);

        if (success)
        {
            currentPresetName = presetName;
            currentPresetModified = false;
            scanUserPresets(); // Refresh list
        }
    }
}

bool PresetManager::loadPreset(const juce::String& presetName, const juce::String& category)
{
    // Search user presets first
    for (size_t i = 0; i < userPresets.size(); ++i)
    {
        if (userPresets[i].name == presetName)
        {
            // When category is provided, require exact match to disambiguate duplicates
            if (category.isNotEmpty() && userPresets[i].category != category)
                continue;

            currentPresetIndex = static_cast<int>(i + factoryPresets.size());
            currentPresetCategory = userPresets[i].category;
            return loadPresetFromFile(userPresets[i].file);
        }
    }

    // Fall back to factory presets
    for (size_t i = 0; i < factoryPresets.size(); ++i)
    {
        if (factoryPresets[i].name == presetName)
        {
            currentPresetIndex = static_cast<int>(i);
            currentPresetCategory = factoryPresets[i].category;
            return loadPresetFromXml(factoryPresets[i].xml.get(), presetName);
        }
    }

    return false;
}

bool PresetManager::deletePreset(const juce::String& presetName, const juce::String& category)
{
    // Can only delete user presets
    for (auto& preset : userPresets)
    {
        if (preset.name == presetName)
        {
            // When category is provided, require exact match to disambiguate duplicates
            if (category.isNotEmpty() && preset.category != category)
                continue;
            if (preset.file.existsAsFile())
            {
            #if JUCE_IOS
                // iOS: moveToTrash() fails in sandboxed containers — use deleteFile()
                bool success = preset.file.deleteFile();
            #else
                bool success = preset.file.moveToTrash();
            #endif
                if (success)
                {
                    scanUserPresets(); // Refresh list
                    if (currentPresetName == presetName)
                    {
                        currentPresetName.clear();
                        currentPresetCategory.clear();
                        currentPresetIndex = -1;
                    }
                }
                return success;
            }
        }
    }
    return false;
}

void PresetManager::randomizeFromPresets()
{
    // Efficient randomization: sample a limited number of presets (max 30)
    // For each parameter, pick a value from a random sampled preset
    // This avoids scanning all 200+ presets while still providing musical results

    const int MAX_PRESET_SAMPLES = 30;
    std::vector<std::unique_ptr<juce::XmlElement>> sampledPresetXmls;

    // Combine all available presets
    std::vector<PresetInfo*> allPresets;
    for (const auto& preset : factoryPresets)
        allPresets.push_back(const_cast<PresetInfo*>(&preset));
    for (const auto& preset : userPresets)
        allPresets.push_back(const_cast<PresetInfo*>(&preset));

    // Handle edge case: no presets available
    if (allPresets.empty())
    {
        // Silently do nothing if no presets exist
        // User can still use the plugin with default/current values
        return;
    }

    // Sample random presets (up to MAX_PRESET_SAMPLES)
    juce::Random random(juce::Time::currentTimeMillis());
    int numToSample = juce::jmin(MAX_PRESET_SAMPLES, static_cast<int>(allPresets.size()));

    for (int i = 0; i < numToSample; ++i)
    {
        int randomIndex = random.nextInt(static_cast<int>(allPresets.size()));
        PresetInfo* presetInfo = allPresets[randomIndex];

        std::unique_ptr<juce::XmlElement> xml;

        if (presetInfo->isFactory && presetInfo->xml)
        {
            // Factory preset - clone the existing XML
            xml = std::make_unique<juce::XmlElement>(*presetInfo->xml);
        }
        else if (presetInfo->file.existsAsFile())
        {
            // User preset - load from file
            xml = juce::XmlDocument::parse(presetInfo->file);
        }

        if (xml != nullptr)
        {
            sampledPresetXmls.push_back(std::move(xml));
        }
    }

    // Handle edge case: failed to load any preset XMLs
    if (sampledPresetXmls.empty())
    {
        return;
    }

    // For each parameter, pick a random value from a random sampled preset
    for (auto* param : audioProcessor.getParameters())
    {
        if (auto* rangedParam = dynamic_cast<juce::RangedAudioParameter*>(param))
        {
            juce::String paramId = rangedParam->getParameterID();

            // Skip *_note parameters (MIDI mapping, not stored in presets)
            if (paramId.endsWith("_note"))
                continue;

            // Pick a random preset from our samples
            int randomPresetIndex = random.nextInt(sampledPresetXmls.size());
            auto* presetXml = sampledPresetXmls[randomPresetIndex].get();

            // Convert XML to ValueTree to access parameters
            auto tree = juce::ValueTree::fromXml(*presetXml);
            if (!tree.isValid())
                continue;

            // Find this parameter in the preset
            for (int i = 0; i < tree.getNumChildren(); ++i)
            {
                auto child = tree.getChild(i);
                if (child.hasType("PARAM"))
                {
                    auto childParamId = child.getProperty("id").toString();
                    if (childParamId == paramId)
                    {
                        auto value = child.getProperty("value");
                        float floatValue = static_cast<float>(value);
                        rangedParam->setValueNotifyingHost(rangedParam->convertTo0to1(floatValue));
                        break;
                    }
                }
            }
        }
    }

    // Mark as modified and clear current preset name
    currentPresetName.clear();
    currentPresetCategory.clear();
    currentPresetModified = true;
    currentPresetIndex = -1;
}

void PresetManager::savePresetAs(const juce::File& file)
{
    juce::File targetFile = file;

    // Ensure .xml extension
    if (!targetFile.hasFileExtension(".xml"))
        targetFile = targetFile.withFileExtension(".xml");

    auto presetName = targetFile.getFileNameWithoutExtension();
    auto xml = createPresetXml(presetName);

    if (xml != nullptr)
    {
        bool success = xml->writeTo(targetFile);

        if (success)
        {
            currentPresetName = presetName;
            currentPresetModified = false;
            scanUserPresets(); // Refresh list
        }
    }
}

bool PresetManager::loadPresetFromFile(const juce::File& file)
{
    if (!file.existsAsFile())
        return false;

    auto xml = juce::XmlDocument::parse(file);
    auto presetName = file.getFileNameWithoutExtension();
    return loadPresetFromXml(xml.get(), presetName);
}

juce::File PresetManager::getCurrentPresetFile() const
{
    // If no preset is loaded, return invalid file
    if (currentPresetIndex < 0)
        return juce::File();

    // Check if it's a factory preset
    if (currentPresetIndex < static_cast<int>(factoryPresets.size()))
    {
        // Factory presets don't have files, return invalid
        return juce::File();
    }

    // It's a user preset - get the file
    int userIndex = currentPresetIndex - static_cast<int>(factoryPresets.size());
    if (userIndex >= 0 && userIndex < static_cast<int>(userPresets.size()))
    {
        return userPresets[userIndex].file;
    }

    return juce::File();
}

juce::StringArray PresetManager::getAllPresetNames() const
{
    juce::StringArray names;

    // Factory presets first
    for (const auto& preset : factoryPresets)
        names.add("[Factory] " + preset.name);

    // Then user presets
    for (const auto& preset : userPresets)
        names.add(preset.name);

    return names;
}

juce::StringArray PresetManager::getFactoryPresetNames() const
{
    juce::StringArray names;
    for (const auto& preset : factoryPresets)
        names.add(preset.name);
    return names;
}

juce::StringArray PresetManager::getUserPresetNames() const
{
    juce::StringArray names;
    for (const auto& preset : userPresets)
        names.add(preset.name);
    return names;
}

juce::File PresetManager::getUserPresetDirectory() const
{
    // Use StorageManager for cross-platform storage with iOS App Groups support
    return StorageManager::getInstance().getPresetsUserDirectory();
}

juce::File PresetManager::getFactoryPresetDirectory() const
{
    juce::File dir;

    #if JUCE_MAC
        dir = juce::File("/Library/Audio/Presets");
    #elif JUCE_WINDOWS
        dir = juce::File::getSpecialLocation(
            juce::File::commonApplicationDataDirectory);
    #elif JUCE_LINUX
        dir = juce::File("/usr/share");
    #endif

    // Use fixed name "AugmaticGRE" without version number for preset directory
    return dir.getChildFile(JucePlugin_Manufacturer)
              .getChildFile("AugmaticGRE");
}

bool PresetManager::loadNextPreset()
{
    // Get the current preset's category to stay within the same folder
    juce::String currentCategory;
    if (currentPresetIndex >= 0)
    {
        if (currentPresetIndex < static_cast<int>(factoryPresets.size()))
        {
            currentCategory = factoryPresets[currentPresetIndex].category;
        }
        else
        {
            int userIndex = currentPresetIndex - static_cast<int>(factoryPresets.size());
            if (userIndex < static_cast<int>(userPresets.size()))
                currentCategory = userPresets[userIndex].category;
        }
    }

    // Find the next preset with the same category
    int startIndex = currentPresetIndex;
    int totalPresets = static_cast<int>(factoryPresets.size() + userPresets.size());

    if (totalPresets == 0)
        return false;

    // Search for next preset in same category
    for (int attempts = 0; attempts < totalPresets; ++attempts)
    {
        currentPresetIndex++;
        if (currentPresetIndex >= totalPresets)
            currentPresetIndex = 0; // Wrap around

        // Check if this preset matches the category
        juce::String candidateCategory;
        if (currentPresetIndex < static_cast<int>(factoryPresets.size()))
        {
            candidateCategory = factoryPresets[currentPresetIndex].category;
        }
        else
        {
            int userIndex = currentPresetIndex - static_cast<int>(factoryPresets.size());
            if (userIndex < static_cast<int>(userPresets.size()))
                candidateCategory = userPresets[userIndex].category;
        }

        // Found a preset in the same category
        if (candidateCategory == currentCategory)
        {
            currentPresetCategory = currentCategory;
            if (currentPresetIndex < static_cast<int>(factoryPresets.size()))
            {
                return loadPresetFromXml(factoryPresets[currentPresetIndex].xml.get(),
                                         factoryPresets[currentPresetIndex].name);
            }
            else
            {
                int userIndex = currentPresetIndex - static_cast<int>(factoryPresets.size());
                return loadPresetFromFile(userPresets[userIndex].file);
            }
        }
    }

    // If we get here, no other preset in same category - stay on current
    currentPresetIndex = startIndex;
    return false;
}

bool PresetManager::loadPreviousPreset()
{
    // Get the current preset's category to stay within the same folder
    juce::String currentCategory;
    if (currentPresetIndex >= 0)
    {
        if (currentPresetIndex < static_cast<int>(factoryPresets.size()))
        {
            currentCategory = factoryPresets[currentPresetIndex].category;
        }
        else
        {
            int userIndex = currentPresetIndex - static_cast<int>(factoryPresets.size());
            if (userIndex < static_cast<int>(userPresets.size()))
                currentCategory = userPresets[userIndex].category;
        }
    }

    // Find the previous preset with the same category
    int startIndex = currentPresetIndex;
    int totalPresets = static_cast<int>(factoryPresets.size() + userPresets.size());

    if (totalPresets == 0)
        return false;

    // Search for previous preset in same category
    for (int attempts = 0; attempts < totalPresets; ++attempts)
    {
        currentPresetIndex--;
        if (currentPresetIndex < 0)
            currentPresetIndex = totalPresets - 1; // Wrap around

        // Check if this preset matches the category
        juce::String candidateCategory;
        if (currentPresetIndex < static_cast<int>(factoryPresets.size()))
        {
            candidateCategory = factoryPresets[currentPresetIndex].category;
        }
        else
        {
            int userIndex = currentPresetIndex - static_cast<int>(factoryPresets.size());
            if (userIndex < static_cast<int>(userPresets.size()))
                candidateCategory = userPresets[userIndex].category;
        }

        // Found a preset in the same category
        if (candidateCategory == currentCategory)
        {
            currentPresetCategory = currentCategory;
            if (currentPresetIndex < static_cast<int>(factoryPresets.size()))
            {
                return loadPresetFromXml(factoryPresets[currentPresetIndex].xml.get(),
                                         factoryPresets[currentPresetIndex].name);
            }
            else
            {
                int userIndex = currentPresetIndex - static_cast<int>(factoryPresets.size());
                return loadPresetFromFile(userPresets[userIndex].file);
            }
        }
    }

    // If we get here, no other preset in same category - stay on current
    currentPresetIndex = startIndex;
    return false;
}

int PresetManager::getCurrentPresetIndex() const
{
    return currentPresetIndex;
}

void PresetManager::rescanUserPresets()
{
    // With security-scoped bookmark architecture, Documents is the single source of truth.
    // No sync needed — both standalone and AUv3 (with bookmark) read/write directly.
    scanUserPresets();
}

