void PresetManager::loadFactoryPresets()
{
    factoryPresets.clear();

    // Factory presets from presets/ are now installed to disk by
    // installFactoryPresetsIfNeeded() and picked up by scanUserPresets().
    // Only the "Init" preset remains as a true in-memory factory preset.
    PresetInfo initPreset;
    initPreset.name = "Init";
    initPreset.isFactory = true;
    initPreset.xml = juce::XmlDocument::parse(kInitPresetXml);

    // Fallback: if static XML parse fails, use current APVTS defaults
    if (initPreset.xml == nullptr)
    {
        auto state = parameters.copyState();
        initPreset.xml = std::unique_ptr<juce::XmlElement>(state.createXml());
    }

    factoryPresets.push_back(std::move(initPreset));
}

juce::File PresetManager::getFactoryPresetsVersionFile() const
{
    return StorageManager::getInstance().getConfigDirectory()
               .getChildFile(".factory_presets_version");
}

void PresetManager::migratePresetsIfNeeded()
{
    auto& storage = StorageManager::getInstance();
    auto dataDir = storage.getDataDirectory();
    auto presetsDir = storage.getPresetsDirectory();

    // If Presets dir is same as data dir, no migration needed
    if (dataDir == presetsDir)
        return;

    // Check for XML files at the old location (data root)
    juce::Array<juce::File> rootXmlFiles;
    dataDir.findChildFiles(rootXmlFiles, juce::File::findFiles, false, "*.xml");

    // Check for category subfolders at the old location
    bool hasCategoryFolders = false;
    juce::Array<juce::File> subfolders;
    dataDir.findChildFiles(subfolders, juce::File::findDirectories, false);
    for (const auto& subfolder : subfolders)
    {
        juce::String name = subfolder.getFileName();
        if (name == "MidiMappings" || name == "Config" || name == "Presets")
            continue;
        juce::Array<juce::File> subXmlFiles;
        subfolder.findChildFiles(subXmlFiles, juce::File::findFiles, false, "*.xml");
        if (!subXmlFiles.isEmpty())
        {
            hasCategoryFolders = true;
            break;
        }
    }

    if (rootXmlFiles.isEmpty() && !hasCategoryFolders)
        return;

    if (!presetsDir.exists())
        presetsDir.createDirectory();

    // Move root-level XML files
    for (const auto& file : rootXmlFiles)
    {
        auto destFile = presetsDir.getChildFile(file.getFileName());
        if (!destFile.exists())
            file.moveFileTo(destFile);
    }

    // Move category subfolders
    for (const auto& subfolder : subfolders)
    {
        juce::String name = subfolder.getFileName();
        if (name == "MidiMappings" || name == "Config" || name == "Presets")
            continue;

        // Only move folders that contain XML files (preset categories)
        juce::Array<juce::File> catFiles;
        subfolder.findChildFiles(catFiles, juce::File::findFiles, false, "*.xml");
        if (catFiles.isEmpty())
            continue;

        auto destFolder = presetsDir.getChildFile(name);
        if (!destFolder.exists())
        {
            subfolder.moveFileTo(destFolder);
        }
        else
        {
            // Merge: move individual files that don't exist at destination
            for (const auto& catFile : catFiles)
            {
                auto destFile = destFolder.getChildFile(catFile.getFileName());
                if (!destFile.exists())
                    catFile.moveFileTo(destFile);
            }
        }
    }
}

void PresetManager::installFactoryPresetsIfNeeded()
{
#if HAS_FACTORY_PRESETS
    auto versionFile = getFactoryPresetsVersionFile();
    juce::String currentVersion = JucePlugin_VersionString;

    // Check if factory presets are already installed for this version
    if (versionFile.existsAsFile())
    {
        juce::String installedVersion = versionFile.loadFileAsString().trim();
        if (installedVersion == currentVersion)
            return;
    }

    // Factory presets are installed to the Factory/ subdirectory (never User/)
    auto factoryDir = StorageManager::getInstance().getPresetsFactoryDirectory();
    if (!factoryDir.exists())
        factoryDir.createDirectory();

    // Build new manifest from current BinaryData
    juce::StringArray newManifest;

    for (int i = 0; i < FactoryPresetData::namedResourceListSize; ++i)
    {
        juce::String originalFilename = FactoryPresetData::originalFilenames[i];

        if (!originalFilename.endsWithIgnoreCase(".xml"))
            continue;

        // Parse category from Category__Filename.xml convention
        juce::String category;
        juce::String presetFilename = originalFilename;

        int separatorIndex = originalFilename.indexOf("__");
        if (separatorIndex >= 0)
        {
            category = originalFilename.substring(0, separatorIndex);
            presetFilename = originalFilename.substring(separatorIndex + 2);
        }

        // Build relative path for manifest (e.g. "Category/Preset.xml" or "Preset.xml")
        juce::String relativePath = category.isNotEmpty()
            ? (category + "/" + presetFilename)
            : presetFilename;
        newManifest.add(relativePath);

        // Determine target directory (inside Factory/)
        juce::File targetDir = factoryDir;
        if (category.isNotEmpty())
        {
            targetDir = factoryDir.getChildFile(category);
            if (!targetDir.exists())
                targetDir.createDirectory();
        }

        juce::File targetFile = targetDir.getChildFile(presetFilename);

        // Get embedded data
        int dataSize;
        const char* data = FactoryPresetData::getNamedResource(
            FactoryPresetData::namedResourceList[i], dataSize);

        if (data == nullptr || dataSize <= 0)
            continue;

        if (!targetFile.exists())
        {
            // File doesn't exist — install it
            targetFile.replaceWithData(data, static_cast<size_t>(dataSize));
        }
        else
        {
            // File exists — only overwrite if embedded presetVersion is higher
            juce::String embeddedContent(data, static_cast<size_t>(dataSize));
            double embeddedVersion = parsePresetVersion(embeddedContent);
            double existingVersion = parsePresetVersion(targetFile.loadFileAsString());

            if (embeddedVersion > existingVersion)
            {
                targetFile.replaceWithData(data, static_cast<size_t>(dataSize));
            }
        }
    }

    // --- Filesystem-based cleanup: delete ANY .xml not in new manifest ---
    // Cleanup runs ONLY inside the Factory/ directory — User/ is NEVER touched.
    // This catches stale factory presets from ALL previous builds, including
    // pre-manifest ones that persist across iOS app reinstalls.
    for (const auto& file : factoryDir.findChildFiles(juce::File::findFiles, false, "*.xml"))
    {
        if (!newManifest.contains(file.getFileName()))
            file.deleteFile();
    }

    for (const auto& dir : factoryDir.findChildFiles(juce::File::findDirectories, false))
    {
        for (const auto& file : dir.findChildFiles(juce::File::findFiles, false, "*.xml"))
        {
            juce::String relativePath = dir.getFileName() + "/" + file.getFileName();
            if (!newManifest.contains(relativePath))
                file.deleteFile();
        }
    }

    // Clean up empty subfolders left after stale file deletion
    for (const auto& dir : factoryDir.findChildFiles(juce::File::findDirectories, false))
    {
        if (dir.findChildFiles(juce::File::findFiles, false, "*.xml").isEmpty())
            dir.deleteRecursively();
    }

    // Save new manifest and version marker
    saveFactoryManifest(newManifest);

    auto configDir = StorageManager::getInstance().getConfigDirectory();
    if (!configDir.exists())
        configDir.createDirectory();
    versionFile.replaceWithText(currentVersion);
#endif
}

void PresetManager::scanUserPresets()
{
    userPresets.clear();

    auto& storage = StorageManager::getInstance();

    // Helper lambda: scan a directory for presets (root + one level of subfolders)
    auto scanDirectory = [this](const juce::File& dir, bool isFactory)
    {
        if (!dir.exists())
            return;

        // Scan root-level .xml files
        for (const auto& file : dir.findChildFiles(juce::File::findFiles, false, "*.xml"))
        {
            PresetInfo info;
            info.name = file.getFileNameWithoutExtension();
            info.file = file;
            info.isFactory = isFactory;
            info.category = "";  // Root level
            userPresets.push_back(std::move(info));
        }

        // Scan one level of subfolders
        for (const auto& subfolder : dir.findChildFiles(juce::File::findDirectories, false))
        {
            juce::String folderName = subfolder.getFileName();

            for (const auto& file : subfolder.findChildFiles(juce::File::findFiles, false, "*.xml"))
            {
                PresetInfo info;
                info.name = file.getFileNameWithoutExtension();
                info.file = file;
                info.isFactory = isFactory;
                info.category = folderName;
                userPresets.push_back(std::move(info));
            }
        }
    };

    // Scan Factory directory (installed from BinaryData)
    scanDirectory(storage.getPresetsFactoryDirectory(), true);

    // Scan User directory (user-created presets)
    scanDirectory(storage.getPresetsUserDirectory(), false);

    // Sort presets by category first, then by name
    std::sort(userPresets.begin(), userPresets.end(),
        [](const PresetInfo& a, const PresetInfo& b)
        {
            if (a.category == b.category)
                return a.name < b.name;
            return a.category < b.category;
        });
}

bool PresetManager::loadPresetFromXml(juce::XmlElement* xml, const juce::String& presetName)
{
    if (xml == nullptr)
        return false;

    auto tree = juce::ValueTree::fromXml(*xml);
    if (!tree.isValid())
        return false;

    // Instead of replacing the entire state, update only the parameters that exist in the preset
    // This preserves any parameters not included in the preset (like *_note parameters)
    for (int i = 0; i < tree.getNumChildren(); ++i)
    {
        auto child = tree.getChild(i);
        if (child.hasType("PARAM"))
        {
            auto paramId = child.getProperty("id").toString();

            // Skip *_note parameters even if they exist in old presets
            if (paramId.endsWith("_note"))
                continue;

            auto value = child.getProperty("value");

            // Update the parameter value
            if (auto* param = parameters.getParameter(paramId))
            {
                float floatValue = static_cast<float>(value);
                param->setValueNotifyingHost(param->convertTo0to1(floatValue));
            }
        }
    }

    // Restore BPM from preset (standalone mode only)
    // In AUv3 mode, host controls tempo - ignore preset BPM
    if (auto* greProcessor = dynamic_cast<AugmaticGREProcessor*>(&audioProcessor))
    {
        if (greProcessor->wrapperType == juce::AudioProcessor::wrapperType_Standalone)
        {
            if (xml->hasAttribute("bpm"))
            {
                int bpm = xml->getIntAttribute("bpm", 120);
                greProcessor->setInternalClockBPM(static_cast<float>(bpm));
            }
        }
    }

    currentPresetName = presetName;
    currentPresetModified = false;

    if (onPresetLoaded)
        onPresetLoaded();

    return true;
}

std::unique_ptr<juce::XmlElement> PresetManager::createPresetXml(const juce::String& presetName)
{
    // Custom XML formatting for human-readable presets
    // Integer parameters saved as integers (no ".0"), floats rounded to 2 decimals
    auto xml = std::make_unique<juce::XmlElement>("AugmaticGRE");

    // Metadata attributes
    xml->setAttribute("presetName", presetName);
    xml->setAttribute("version", JucePlugin_VersionString);
    xml->setAttribute("presetVersion", "1.0");
    xml->setAttribute("dateCreated", juce::Time::getCurrentTime().toISO8601(true));

    // Save internal clock BPM (not in APVTS, restored only in standalone mode)
    if (auto* greProcessor = dynamic_cast<AugmaticGREProcessor*>(&audioProcessor))
    {
        xml->setAttribute("bpm", static_cast<int>(greProcessor->getInternalClockBPM()));
    }

    // Iterate through all parameters and format based on type
    for (auto* param : audioProcessor.getParameters())
    {
        if (auto* rangedParam = dynamic_cast<juce::RangedAudioParameter*>(param))
        {
            juce::String paramId = rangedParam->getParameterID();

            // Skip *_note parameters (managed by MIDI Mapping system)
            if (paramId.endsWith("_note"))
                continue;

            auto* paramElement = xml->createNewChildElement("PARAM");
            paramElement->setAttribute("id", paramId);

            // Format value based on parameter type
            if (auto* intParam = dynamic_cast<juce::AudioParameterInt*>(rangedParam))
            {
                // Integer parameters: no decimal point
                paramElement->setAttribute("value", intParam->get());
            }
            else if (auto* boolParam = dynamic_cast<juce::AudioParameterBool*>(rangedParam))
            {
                // Boolean parameters: 0 or 1 (no decimal)
                paramElement->setAttribute("value", boolParam->get() ? 1 : 0);
            }
            else if (auto* choiceParam = dynamic_cast<juce::AudioParameterChoice*>(rangedParam))
            {
                // Choice parameters: index as integer
                paramElement->setAttribute("value", choiceParam->getIndex());
            }
            else if (auto* floatParam = dynamic_cast<juce::AudioParameterFloat*>(rangedParam))
            {
                // Float parameters: round to 2 decimal places for readability
                // This is sufficient for float parameters mapped to MIDI CC values
                float value = floatParam->get();
                paramElement->setAttribute("value", juce::String(value, 2));
            }
        }
    }

    return xml;
}

juce::File PresetManager::getPresetsBaseDirectory() const
{
    // Use StorageManager for cross-platform storage with iOS App Groups support
    return StorageManager::getInstance().getPresetsDirectory();
}

std::vector<PresetManager::PresetItem> PresetManager::getAllPresetsWithCategories() const
{
    std::vector<PresetItem> items;

    // Add factory presets (no category)
    for (const auto& preset : factoryPresets)
    {
        PresetItem item;
        item.name = preset.name;
        item.category = "";  // Factory presets don't have categories
        item.isFactory = true;
        items.push_back(item);
    }

    // Add user presets with their categories
    for (const auto& preset : userPresets)
    {
        PresetItem item;
        item.name = preset.name;
        item.category = preset.category;
        item.isFactory = false;
        items.push_back(item);
    }

    return items;
}

juce::File PresetManager::getFactoryManifestFile() const
{
    return StorageManager::getInstance().getConfigDirectory()
               .getChildFile(".factory_presets_manifest");
}

void PresetManager::saveFactoryManifest(const juce::StringArray& relativePaths) const
{
    auto configDir = StorageManager::getInstance().getConfigDirectory();
    if (!configDir.exists())
        configDir.createDirectory();

    getFactoryManifestFile().replaceWithText(relativePaths.joinIntoString("\n"));
}

double PresetManager::parsePresetVersion(const juce::String& xmlContent)
{
    // Fast extraction: find presetVersion="..." without full XML parse
    int idx = xmlContent.indexOf("presetVersion=\"");
    if (idx < 0)
        return 0.0;

    idx += 15; // length of 'presetVersion="'
    int endIdx = xmlContent.indexOf(idx, "\"");
    if (endIdx < 0)
        return 0.0;

    return xmlContent.substring(idx, endIdx).getDoubleValue();
}